<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';$id=(int)($_GET['id']??0);$uid=trim((string)($_GET['uid']??''));$document=(new App\Domain\NeedRequest\NeedRequestRepository(app_database()))->verify($id,$uid);http_response_code($document?200:404);?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vérification FEB · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{display:grid;min-height:100vh;place-items:center;background:#f5f6fa}.verify{width:min(560px,calc(100% - 28px));padding:32px;background:#fff;border-radius:22px;box-shadow:0 20px 60px #22254b22}.logo{width:120px;margin-bottom:25px}.ok{color:#167346}.bad{color:#b6404a}</style></head><body><main class="verify"><img class="logo" src="img/logo_fidest.png" alt="FIDEST"><?php if($document):?><h1 class="h4 ok">Document authentifié</h1><p>Cette FEB est enregistrée dans le système documentaire FIDEST.</p><dl class="row small"><dt class="col-5">Identifiant</dt><dd class="col-7"><?=htmlspecialchars($document['document_uid'])?></dd><dt class="col-5">Référence</dt><dd class="col-7"><?=htmlspecialchars($document['numero_feb'])?></dd><dt class="col-5">Version</dt><dd class="col-7"><?=htmlspecialchars($document['document_version'])?></dd><dt class="col-5">Statut</dt><dd class="col-7"><?=htmlspecialchars($document['statut'])?></dd></dl><?php else:?><h1 class="h4 bad">Document non reconnu</h1><p>L’identifiant transmis ne correspond à aucune FEB enregistrée.</p><?php endif;?></main></body></html>
